cat > /tmp/validate_ie.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const errors = [], failedReqs = [];
    page.on('pageerror', e => errors.push('pageerror: ' + e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
    page.on('requestfailed', r => failedReqs.push(r.url() + ' :: ' + (r.failure()||{}).errorText));
    const out = {};

    // --- Main page ---
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle', timeout: 30000 });
    await page.waitForTimeout(4000);
    out.title = await page.title();
    out.indexOptions = await page.$eval('#chooseIndex', el => Array.from(el.options).map(o => o.textContent.trim())).catch(e => 'ERR ' + e.message);

    // Choose the spotify_tracks index
    const opts = out.indexOptions;
    const spotifyOpt = Array.isArray(opts) ? opts.find(o => o.toLowerCase().includes('spotify')) : null;
    out.selected = spotifyOpt;
    if (spotifyOpt) {
        await page.selectOption('#chooseIndex', { label: spotifyOpt });
        await page.waitForTimeout(5000);
        // pick first available field
        const fields = await page.$eval('#dataExplorerDataFields', el => Array.from(el.options).map(o => o.textContent.trim())).catch(e => 'ERR ' + e.message);
        out.spotifyFields = fields;
        if (Array.isArray(fields) && fields.length > 1) {
            await page.selectOption('#dataExplorerDataFields', { index: 1 });
            await page.waitForTimeout(1500);
            await page.click('#getResults');
            await page.waitForTimeout(8000);
            out.svgCount = await page.locator('#graphicsWrapper svg').count();
            out.tableRows = await page.locator('#graphicsWrapper table tr').count().catch(()=>0);
            out.feedback = (await page.$eval('#feedbackText', el => el.textContent.trim()).catch(() => '')) || '(empty)';
            await page.screenshot({ path: '/tmp/validate_ie_main_search.png', fullPage: true });
        }
    }

    // --- Second example page (komono) loads and initializes ---
    const page2 = await browser.newPage();
    const errs2 = [];
    page2.on('pageerror', e => errs2.push(e.message));
    await page2.goto('http://localhost/examples/komono/index.html', { waitUntil: 'networkidle', timeout: 30000 });
    await page2.waitForTimeout(5000);
    out.komono_loaded = await page2.title();
    out.komono_errors = errs2;

    out.errors = errors;
    out.failedReqs = failedReqs.slice(0, 10);
    console.log('IE_VALIDATE_RESULTS:' + JSON.stringify(out, null, 2));
    await browser.close();
})().catch(e => { console.error('IE_VALIDATE_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node /tmp/validate_ie.js 2>&1 | tail -60
